// RELATED: ethereum/executionlayer/src/main/java/tech/pegasys/teku/ethereum/executionlayer/BuilderBidValidatorImpl.java:expectedGasLimit (lines 132-141)
// Teku checks gas limit change is bounded within 1/1024 per block for builder bids:
  static UInt64 expectedGasLimit(final UInt64 parentGasLimit, final UInt64 targetGasLimit) {
    final UInt64 maxGasLimitDifference = parentGasLimit.dividedBy(1024L).minusMinZero(1);
    if (targetGasLimit.isGreaterThan(parentGasLimit)) {
      final UInt64 gasDiff = targetGasLimit.minusMinZero(parentGasLimit);
      return parentGasLimit.plus(maxGasLimitDifference.min(gasDiff));
    } else {
      final UInt64 gasDiff = parentGasLimit.minusMinZero(targetGasLimit);
      return parentGasLimit.minusMinZero(maxGasLimitDifference.min(gasDiff));
    }
  }

// PRIMARY: ethereum/spec/src/main/java/tech/pegasys/teku/spec/datastructures/execution/versions/electra/ExecutionRequestsDataCodec.java:encode (lines 93-126)
// Teku encodes execution requests in strictly ascending type order: deposits(0), withdrawals(1), consolidations(2)
  public List<Bytes> encode(final ExecutionRequests executionRequests) {
    final List<Bytes> executionRequestsData = new ArrayList<>();
    final List<DepositRequest> deposits = executionRequests.getDeposits();
    if (!deposits.isEmpty()) {
      executionRequestsData.add(Bytes.concatenate(DepositRequest.REQUEST_TYPE_PREFIX, ...));
    }
    final List<WithdrawalRequest> withdrawals = executionRequests.getWithdrawals();
    if (!withdrawals.isEmpty()) {
      executionRequestsData.add(Bytes.concatenate(WithdrawalRequest.REQUEST_TYPE_PREFIX, ...));
    }
    final List<ConsolidationRequest> consolidations = executionRequests.getConsolidations();
    if (!consolidations.isEmpty()) {
      executionRequestsData.add(Bytes.concatenate(ConsolidationRequest.REQUEST_TYPE_PREFIX, ...));
    }
    return executionRequestsData;
  }

